function queueTime(seconds){const value=Math.max(0,Number(seconds)||0);if(value<60)return`${Math.max(1,Math.round(value))} 秒`;if(value<3600)return`${Math.max(1,Math.round(value/60))} 分钟`;const hours=Math.floor(value/3600),minutes=Math.round(value%3600/60);return minutes?`${hours} 小时 ${minutes} 分钟`:`${hours} 小时`}
