function queueClock(seconds){const total=Math.max(0,Math.floor(Number(seconds)||0)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),secs=total%60,pad=value=>String(value).padStart(2,'0');return hours?`${hours}:${pad(minutes)}:${pad(secs)}`:`${pad(minutes)}:${pad(secs)}`}
