function compactQueuePhase(task){
  const phase=String(task.progress_phase||''),key=String(task.progress_phase_key||'');
  if(key==='sampling')return'采样中';
  if(key==='flux_loading')return phase.includes('编码')?'Flux 分块编码':'加载 Flux';
  if(key==='saving')return'保存结果';
  if(key==='seedvr2')return'SeedVR2 放大';
  if(key==='cleanup')return'释放显存';
  if(key==='encoding'){
    if(phase.includes('图1原图'))return'编码双参考图';
    if(phase.includes('身份参考图'))return'编码身份参考图';
    if(phase.includes('参考图'))return'编码参考图';
    return'编码提示词'
  }
  if(key==='postprocess'){
    if(phase.includes('VAE'))return'VAE 解码';
    if(phase.includes('色彩'))return'色彩匹配';
    if(phase.includes('颗粒'))return'添加颗粒';
    if(phase.includes('亮度'))return'调整亮度';
    return'图像后处理'
  }
  if(key==='dispatching')return'提交工作流';
  if(key==='cancelling')return'停止中';
  if(key==='loading'){
    if(phase.includes('官方 Krea2'))return'加载官方 Krea2';
    if(phase.includes('Qwen'))return'加载 Qwen';
    if(phase.includes('SeedVR2'))return'加载 SeedVR2';
    if(phase.includes('Flux'))return'加载 Flux';
    return'加载模型'
  }
  return phase.replace(/^正在/,'').replace(/当前图像|当前任务/g,'').trim()||'处理中'
}
