  if(!parameters.turbo_lora||parameters.duration===undefined)return view;
  view.core=view.core.filter(item=>item[0]!=='数量');
  view.core=view.core.map(item=>item[0]==='画幅'&&parameters.mode==='i2v'?['画幅','跟随原图']:item);
  view.core.unshift(['生成方式',parameters.mode==='i2v'?'图生视频':'文生视频']);
  view.core.push(['时长',String(parameters.duration)+' 秒']);
  if(Number(parameters.h3_lottery_count)>1)view.core.push(['批量抽奖',`${parameters.h3_lottery_count} 次`]);
  view.sampling.push(['Turbo LoRA',cleanLoraName(parameters.turbo_lora)]);
  if(parameters.low_vram)view.sampling.push(['低显存模式','开启']);
  const actualSeeds=Array.isArray(parameters.generation_seeds)&&parameters.generation_seeds.length?parameters.generation_seeds:parameters.seed===undefined?[]:[parameters.seed];
