function addedOwnGenerationCount(previous,next){const active=snapshot=>new Set((snapshot?.tasks||[]).filter(task=>task.own&&task.kind==='generation'&&task.record_id).map(task=>String(task.record_id))),before=active(previous),after=active(next);let count=0;after.forEach(id=>{if(!before.has(id))count++});return count}
